def transform(grid):
    """Replace solid monochrome rectangular patches at least 3x5 with 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for top in range(h):
        # Keep columns whose values remain the same across this row span.
        common = [True] * w
        for bottom in range(top, h):
            if bottom > top:
                for c in range(w):
                    if grid[bottom][c] != grid[bottom - 1][c]:
                        common[c] = False
            if bottom - top + 1 < 4:
                continue
            c = 0
            while c < w:
                if not common[c]:
                    c += 1
                    continue
                color = grid[top][c]
                end = c + 1
                while end < w and common[end] and grid[top][end] == color:
                    end += 1
                if end - c >= 5:
                    for r in range(top, bottom + 1):
                        for x in range(c, end):
                            out[r][x] = 4
                c = end
    return out
